/**
 * Private object storage contract. Domain code depends ONLY on this interface; S3/GCS/Azure are new
 * implementations. Keys are always generated by the application (never derived from user input) and
 * objects are never publicly readable: access goes through our authorised, short-lived signed URLs.
 */
export interface StoredObjectInfo {
  key: string;
  size: number;
}

export interface StorageProvider {
  readonly name: string;
  put(
    key: string,
    data: Buffer,
    meta: { contentType: string; sha256: string },
  ): Promise<StoredObjectInfo>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
}
